import re, subprocess
def sh(*a): return subprocess.run(a, capture_output=True, text=True, check=True).stdout
old_rev = "a5d8770"
targets = {"README.md": r"(?<![\w/.-])README\.md", "evals/README.md": r"evals/README\.md"}
files = ["docs/controls.md", "docs/threat-model.md"] + [f for f in sh("git","ls-files","*.md").split("\n") if f and "/results/raw/" not in f and not f.startswith("docs/")]
data = {t: (sh("git","show",f"{old_rev}:{t}").split("\n"), open(t).read().split("\n")) for t in targets}
log = []
def remap(t, n):
    old, new = data[t]
    if n > len(old): return None
    txt = old[n-1].strip()
    if not txt: return None
    hits = [k+1 for k, l in enumerate(new) if l.strip() == txt]
    if new[n-1].strip() == txt and len(hits) >= 1 and n in hits: return n
    return hits[0] if len(hits) == 1 else None
unres = []
for f in files:
    s = open(f, encoding="utf-8").read(); orig = s
    for t, pat in targets.items():
        def sub(m):
            a = int(m.group(2)); na = remap(t, a)
            if na is None: unres.append((f, t, a)); return m.group(0)
            out = m.group(1) + str(na)
            if m.group(3):
                b = int(m.group(4)); nb = remap(t, b)
                if nb is None: unres.append((f, t, b)); nb = b
                out += m.group(3) + str(nb)
            if out != m.group(0): log.append((f, m.group(0), out, data[t][0][a-1].strip()[:60]))
            return out
        s = re.sub(r"(" + pat + r":)(\d+)(?:(`-`:)(\d+))?", sub, s)
    if s != orig: open(f, "w", encoding="utf-8").write(s)
for l in log: print(l)
print("unresolved:", unres)
EOF

